// This film is generated by clean production preparation and the real accepted-
// hit entry, not by manufacturing an event/checkpoint or an outcome screen.
func viewerFilm(t *testing.T, total ...int) (*FrontEnd, *replay.Film) {
	t.Helper()
	c := developmentScenarioController(t, "o-clean-flight")
	if e := c.Handle(Actions{Cancel: true}); e != nil {
		t.Fatal(e)
	}
	c.Handle(Actions{})
	c.Handle(Actions{FlightCommands: []int{2}})
	for i := 0; i < 28; i++ {
		if i >= 8 {
			hits := 0
			if len(total) == 0 && i == 8 {
				hits = 1
			}
			if len(total) > 0 {
				hits = min(16, max(0, total[0]-16*(i-8)))
			}
			for hit := 0; hit < hits; hit++ {
				seed := uint16(0x0140)
				if len(total) > 0 {
					seed = 0x0320
				}
				if e := c.Rendering.QueueAcceptedPlayerHit(AcceptedPlayerHit{VictimRow: 0, Source: "StepO labelled supplied accepted-hit consumer", developmentSeed: &seed}); e != nil {
					t.Fatal(e)
				}
			}
		}
		if e := c.advanceFlight(.1); e != nil {
			t.Fatal(e)
		}
		if c.Screen == ScreenQuit {
			c.cancelNaturalSortieEnd()
			c.Screen = ScreenScene
			c.Rendering.clearFlightInput()
		}
	}
	if e := c.Handle(Actions{EndMission: true}); e != nil {
		t.Fatal(e)
	}
	if e := c.Handle(Actions{ConfirmQuit: true}); e != nil {
		t.Fatal(e)
	}
	f, e := c.SealRecordedFilm()
	if e != nil {
		t.Fatal(e)
	}
	if f == nil {
		t.Fatal("no real film")
	}
	n := 0
	for _, o := range f.Operations {
		n += len(o.Events)
	}
	if n == 0 {
		t.Fatal("real accepted hit did not emit a source result event")
	}
	return c, f
}
func openViewer(t *testing.T, c *FrontEnd, f *replay.Film) {
	t.Helper()
	q, e := NewFilmPlayback(c.Office.Assets, f, c.Runtime)
	if e != nil {
		t.Fatal(e)
	}
	c.Viewer = NewReplayViewer(q)
	c.Library = &FilmLibrary{Store: replay.Store{Root: t.TempDir()}}
	c.Screen = ScreenReplay
}
func TestVCRSourceRegionsAndInput(t *testing.T) {
	c, f := viewerFilm(t)
	openViewer(t, c, f)
	want := [][5]int{{33, 172, 52, 181, 0x1372}, {53, 172, 72, 181, 0x1f73}, {73, 172, 92, 181, 0x1970}, {93, 172, 112, 181, 0x316e}, {113, 172, 131, 181, 0x2166}, {11, 170, 22, 175, 0x4800}, {11, 183, 23, 188, 0x5000}, {7, 175, 11, 183, 0x4b00}, {22, 175, 27, 183, 0x4d00}, {137, 172, 145, 181, 0x0231}, {146, 172, 154, 181, 0x0332}, {155, 172, 163, 181, 0x0433}, {164, 172, 172, 181, 0x0534}, {173, 172, 181, 181, 0x0635}, {182, 172, 190, 181, 0x1474}, {235, 172, 255, 181, 0x3200}, {256, 172, 290, 181, 0x2d00}, {291, 172, 315, 181, 0x1500}}
	for i, w := range want {
		r := c.Office.Assets.Replay.ViewerRegions[i]
		if [5]int{r.X1, r.Y1, r.X2, r.Y2, int(r.Command)} != w {
			t.Fatal("source CS226d table", i, r)
		}
		x, y := (r.X1+r.X2)/2, (r.Y1+r.Y2)/2
		if c.replayHit(x, y) != i || c.replayHit(r.X1, y) == i || c.replayHit(r.X2, y) == i || c.replayHit(x, r.Y1) == i || c.replayHit(x, r.Y2) == i {
			t.Fatal("strict interior", i)
		}
	}
	if e := c.handleReplay(Actions{ReplayMap: true, Text: []rune("m")}); e != nil {
		t.Fatal(e)
	}
	if !c.Viewer.Map || c.Viewer.MapDetails {
		t.Fatal("AltM must not also apply plainM's separate carrier")
	}
	c.handleReplay(Actions{Text: []rune("m")})
	if !c.Viewer.Map || !c.Viewer.MapDetails {
		t.Fatal("plainM changed map visibility rather than detail carrier")
	}
	c.handleReplay(Actions{ReplayMap: true})
	if c.Viewer.Map {
		t.Fatal("AltM did not close the map")
	}
	if e := c.handleReplay(Actions{Inside: true, X: 60, Y: 176, PointerPressed: true}); e != nil {
		t.Fatal(e)
	}
	if !c.Viewer.Stopped {
		t.Fatal("mouse Stop did not stop")
	}
	cursor := c.Viewer.Playback.Cursor
	c.AdvanceReplay(2)
	if c.Viewer.Playback.Cursor != cursor {
		t.Fatal("Stop consumed film")
	}
	c.handleReplay(Actions{Text: []rune("p")})
	if c.Viewer.Stopped {
		t.Fatal("keyboard Play")
	}
	c.handleReplay(Actions{MenuBackTab: true})
	if c.Viewer.Selected != 1 {
		t.Fatal("reverse selection")
	}
	c.handleReplay(Actions{MenuTab: true})
	if c.Viewer.Selected != 2 {
		t.Fatal("forward selection")
	}
	c.handleReplay(Actions{Text: []rune("s")})
	c.handleReplay(Actions{Enter: true})
	if !c.Viewer.Stopped {
		t.Fatal("Enter activates selected region")
	}
}
func TestVCRViewerIsolationAndRealNext(t *testing.T) {
	c, f := viewerFilm(t)
	openViewer(t, c, f)
	v := c.Viewer
	p := v.Playback.Preview()
	before := p.FilmCheckpoint()
	control := p.ViewControls.ReplayState()
	state := c.Store.State()
	for _, a := range []Actions{{Up: true}, {Right: true}, {Text: []rune("t")}, {ReplayMap: true}, {Text: []rune("m")}, {ReplayDemo: true}, {Text: []rune("1")}} {
		if e := c.handleReplay(a); e != nil {
			t.Fatal(e)
		}
		x := append([]byte(nil), c.replayFrame(true)...)
		y := c.replayFrame(true)
		if !bytes.Equal(x, y) {
			t.Fatal("stationary viewer redraw unstable")
		}
		if !reflect.DeepEqual(before, p.FilmCheckpoint()) || !reflect.DeepEqual(control, p.ViewControls.ReplayState()) {
			t.Fatal("viewer mutated recorded controls/checkpoint")
		}
	}
	if !reflect.DeepEqual(state, c.Store.State()) || v.Playback.Engine.Store != nil {
		t.Fatal("viewer acquired career capability")
	}
	c.handleReplay(Actions{Text: []rune("n")})
	for i := 0; i < 100 && v.Next; i++ {
		if e := c.AdvanceReplay(.05); e != nil {
			t.Fatal(e)
		}
	}
	if v.Next || v.Fast || v.Playback.EventCount == 0 || v.Playback.Divergence != "" {
		t.Fatal("Next did not stop after real accepted-damage event", v.Playback.Cursor, v.Playback.Divergence)
	}
	last := f.Operations[v.Playback.Cursor-1]
	if last.Kind != "step" || len(last.Events) == 0 {
		t.Fatal("Next stopped away from completed event step")
	}
	for _, e := range last.Events {
		if e.Kind != 2 {
			t.Fatal("fixture no longer accepted-damage event", e)
		}
	}
	if e := c.activateReplayControl(0); e != nil {
		t.Fatal(e)
	}
	if c.Viewer.Playback.Cursor != 0 || c.Viewer.Playback.EventCount != 0 || !c.Viewer.AudioReset {
		t.Fatal("rewind failed clean reconstruction/channel reset")
	}
	c.handleReplay(Actions{ReplayResume: true})
	if !c.Viewer.Practice || !c.Viewer.Playback.Practice || c.Viewer.Playback.Engine.Store != nil {
		t.Fatal("isolated Resume")
	}
	c.AdvanceReplay(.2)
	if c.Viewer.Playback.Preview().Flight.Steps == 0 {
		t.Fatal("practice did not run real mechanics")
	}
}

func TestVCRHostViewRateSchedulesPreserveAuthoritativeFilm(t *testing.T) {
	c, f := viewerFilm(t)
	var expected map[string]string
	for _, hz := range []int{30, 60, 144} {
		for _, scale := range []int{1, 2} {
			for _, mode := range []string{"smooth", "stepped"} {
				c.Runtime.SimulationRenderScale = scale
				c.Runtime.PresentationMode = mode
				openViewer(t, c, f)
				v := c.Viewer
				for host := 0; c.Screen == ScreenReplay && host < 3000; host++ {
					if host%11 == 0 {
						c.handleReplay(Actions{Right: true})
					}
					if host%17 == 0 {
						c.handleReplay(Actions{ReplayMap: true})
					}
					if host == 2 {
						c.handleReplay(Actions{Text: []rune("f")})
					}
					if e := c.AdvanceReplay(1 / float64(hz)); e != nil {
						t.Fatal(e)
					}
					if c.Screen == ScreenReplay {
						before := v.Playback.Preview().FilmCheckpoint()
						c.replayFrame(false)
						c.replayFrame(true)
						if !reflect.DeepEqual(before, v.Playback.Preview().FilmCheckpoint()) {
							t.Fatal("draw changed film", hz, scale, mode)
						}
					}
				}
				if !v.Playback.Done || v.Playback.Divergence != "" || c.Screen != ScreenFilms {
					t.Fatal("viewer did not reach identical end", hz, scale, mode, v.Playback.Divergence)
				}
				got := v.Playback.Preview().FilmCheckpoint()
				if expected == nil {
					expected = got
				} else if !reflect.DeepEqual(expected, got) {
					t.Fatal("host/viewer scheduling changed final film", hz, scale, mode)
				}
			}
		}
	}
}

func TestVCRNextCompletesMultipleRealEvents(t *testing.T) {
	c, f := viewerFilm(t, 2)
	events := []replay.Event{}
	multi := false
	for _, o := range f.Operations {
		events = append(events, o.Events...)
		if len(o.Events) > 1 {
			multi = true
		}
	}
	if !multi || len(events) != 2 {
		t.Fatal("production event/wrap fixture did not reach boundary", len(events))
	}

	openViewer(t, c, f)
	v := c.Viewer
	for v.Playback.EventCount < uint64(len(events)) {
		start := v.Playback.EventCount
		if e := c.activateReplayControl(3); e != nil {
			t.Fatal(e)
		}
		for h := 0; h < 100 && v.Next; h++ {
			if e := c.AdvanceReplay(.05); e != nil {
				t.Fatal(e)
			}
		}
		if v.Next || v.Playback.Divergence != "" || v.Playback.EventCount <= start {
			t.Fatal("Next confused wrapped ring byte with monotonic event boundary", v.Playback.Divergence)
		}
		op := f.Operations[v.Playback.Cursor-1]
		if op.Kind != "step" || len(op.Events) == 0 || v.Playback.EventCount-start != uint64(len(op.Events)) {
			t.Fatal("Next split real source events within one logical step")
		}
	}
	// No later event exists: ordinary EOF returns the existing library token.
	c.activateReplayControl(3)
	for h := 0; h < 100 && c.Screen == ScreenReplay; h++ {
		c.AdvanceReplay(.05)
	}
	if c.Screen != ScreenFilms || !v.Playback.Done || v.Playback.Divergence != "" {
		t.Fatal("no-event EOF stalled or diverged")
	}
}

// A supplied retained ring byte probes the actual source producer/observer
// adapter, not natural reachability or a forged finished film checkpoint.
func TestVCRSourceEventBridgeRetainsByteWrap(t *testing.T) {
	c, f := viewerFilm(t)
	openViewer(t, c, f)
	q := c.Viewer.Playback
	s := q.Preview().Flight.Combat
	s.Results[3].Sequence = 254
	for i := 0; i < 4; i++ {
		if e := s.RecordAcceptedPlayerHit(0, 11, 0x1234); e != nil {
			t.Fatal(e)
		}
	}
	if q.EventCount != 4 || len(q.events) != 4 {
		t.Fatal("observer dropped shifted ring events")
	}
	for i, w := range []byte{255, 0, 1, 2} {
		e := q.events[i]
		if e.Sequence != w || e.Index != uint64(i+1) || e.Kind != 2 || e.Actor != 0 || e.Target != 11 || e.Timestamp != 0x1234 {
			t.Fatal("source ring/monotonic film domain conflation", i, e)
		}
	}
}

func TestVCRPreparedPanelSurroundsSourceViewport(t *testing.T) {
	c, f := viewerFilm(t)
	for _, scale := range []int{1, 2} {
		c.Runtime.SimulationRenderScale = scale
		openViewer(t, c, f)
		frame := c.replayFrame(false)
		panel := c.Office.Assets.Replay.ViewerPanel
		// Exact source artwork coordinates, including the sidebar title, scene
		// frame, controller frame and ESC TO EXIT footer, outside mutable regions.
		for _, p := range [][2]int{{0, 0}, {227, 40}, {229, 100}, {240, 5}, {232, 40}, {319, 100}, {0, 167}, {0, 168}, {40, 185}, {150, 195}} {
			for sy := 0; sy < scale; sy++ {
				for sx := 0; sx < scale; sx++ {
					got := frame[(p[1]*scale+sy)*320*scale+p[0]*scale+sx]
					if got != panel[p[1]*320+p[0]] {
						t.Fatal("original loose panel replaced by world projection", scale, p, got, panel[p[1]*320+p[0]])
					}
				}
			}
		}
	}
}

func TestVCRTerminalFastHonorsEveryPresentationTransaction(t *testing.T) {
	c := historicalCriticalFuelScenario(t, "o-terminal")
	c.Handle(Actions{Cancel: true})
	for i := 0; i < 1000 && c.Rendering != nil; i++ {
		if e := c.AdvanceRendering(.12); e != nil {
			t.Fatal(e)
		}
	}
	if c.Rendering != nil {
		t.Fatal("real accepted fuel hits did not terminate")
	}
	f, e := c.SealRecordedFilm()
	if e != nil {
		t.Fatal(e)
	}
	for _, scale := range []int{1, 2} {
		for _, mode := range []string{"smooth", "stepped"} {
			for _, hz := range []int{4, 10, 60} {
				c.Runtime.SimulationRenderScale = scale
				c.Runtime.PresentationMode = mode
				openViewer(t, c, f)
				v := c.Viewer
				p := v.Playback.Preview()
				r := p.Flight
				r.RequireTerminalAck = true
				if e = c.activateReplayControl(4); e != nil || !v.Fast || v.Next {
					t.Fatal("fast continuous control", e)
				}
				delivered := 0
				for host := 0; c.Screen == ScreenReplay && host < 1000; host++ {
					if e := c.AdvanceReplay(1 / float64(hz)); e != nil {
						t.Fatal(e)
					}
					if c.Screen != ScreenReplay {
						break
					}
					if r.terminalAwaitingAck {
						delivered++
						cursor := v.Playback.Cursor
						before := p.FilmCheckpoint()
						if e := c.AdvanceReplay(3); e != nil {
							t.Fatal(e)
						}
						if v.Playback.Cursor != cursor || !reflect.DeepEqual(before, p.FilmCheckpoint()) {
							t.Fatal("undelivered transaction advanced")
						}
						frame := bytes.Clone(c.replayFrame(false))
						if len(frame) == 0 || !bytes.Equal(frame, c.replayFrame(false)) || r.TerminalPresentation.Frames != uint64(delivered) {
							t.Fatalf("unstable or missing terminal frame %d at %dHz, scale=%d mode=%s", delivered, hz, scale, mode)
						}
						if !reflect.DeepEqual(before, p.FilmCheckpoint()) {
							t.Fatal("terminal drawing advanced logical source")
						}
						if v.Fast || v.Next {
							t.Fatal("terminal kept accelerated debt")
						}
						c.MarkScenePresented()
					}
				}
				t.Logf("scale=%d mode=%s hostHz=%d delivered=%d terminalIterations=%d", scale, mode, hz, delivered, r.TerminalPresentation.Frames)
				if !v.Playback.Done || v.Playback.Divergence != "" || delivered != 3 || r.TerminalPresentation.Frames != 4 || r.TerminalPresentation.Fade {
					t.Fatal("terminal nonfinal/final ordering", scale, mode, delivered, r.TerminalPresentation, v.Playback.Divergence)
				}
			}
		}
	}
}
